} from "@mui/material";
import { useTheme } from "@mui/material/styles";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import type { HomePlans, PlanCard, PlanGroup, PlanInnerTab, PlanTab } from "../types/home";
import PlanLearnMoreModal from "./PlanLearnMoreModal";
import plansBg from "../assets/Frame-1000005851.png";

const BLUE = "#759ae1";
const NAVY = "#17224d";

function Heading({ title, highlight }: { title?: string; highlight?: string }) {
  if (!title && !highlight) return null;
  if (title && highlight && title.includes(highlight)) {
    const index = title.indexOf(highlight);
    return (
      <>
        {title.slice(0, index)}
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
        {title.slice(index + highlight.length)}
      </>
    );
  }
  return (
    <>
      {title}{" "}
      {highlight ? (
        <Box component="span" sx={{ color: BLUE }}>
          {highlight}
        </Box>
      ) : null}
    </>
  );
}

function PlanItem({
  plan,
  selected,
  onSelect,
  onLearnMore,
}: {
  plan: PlanCard;
  selected: string;
  onSelect: (duration: string) => void;
  onLearnMore: () => void;
}) {
  const canBuy = Boolean(plan.buyUrl && selected);

  return (
    <Box
      sx={{
        width: "100%",
        minWidth: 0,
        backgroundColor: "#fff",
        borderRadius: "15px",
        boxShadow: "0 4px 20px 0 rgba(0,0,0,0.10)",
        height: "100%",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
      }}
    >
      <Box
        sx={{
          backgroundColor: "#e7efff",
          borderTopLeftRadius: "15px",
          borderTopRightRadius: "15px",
          minHeight: 150,
          height: 150,
          px: 3,
          py: 3,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}
      >
        <Typography
          sx={{
            fontSize: { xs: 20, sm: 22, md: 26, tv: 28 },
            fontWeight: 700,
            letterSpacing: "0.26px",
            lineHeight: 1.2,
            mb: 1.5,
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
            overflow: "hidden",
            minHeight: 62,
            background: "linear-gradient(180deg, #17224d 0%, #759ae1 100%)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
          }}
        >
          {plan.title}
        </Typography>
        <Box
          component="button"
          type="button"
          onClick={onLearnMore}
          sx={{
            color: BLUE,
            fontWeight: 700,
            fontSize: 16,
            textDecoration: "none",
            width: "fit-content",
            border: 0,
            background: "none",
            padding: 0,
            cursor: "pointer",
            fontFamily: "inherit",
          }}
        >
          Learn More
        </Box>
      </Box>
      <Box sx={{ px: 2.5, py: 2, flex: 1, display: "flex", flexDirection: "column" }}>
        <Stack spacing={0.5} sx={{ flex: 1, justifyContent: "flex-start" }}>
          {(plan.prices || []).map((price) => {
            const active = selected === price.duration;
            return (
              <Stack
                key={price.id || price.duration}
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                onClick={() => onSelect(price.duration)}
                sx={{ py: 1, cursor: "pointer" }}
              >
                <Stack direction="row" alignItems="center" spacing={0.5}>
                  <Radio
                    checked={active}
                    onChange={() => onSelect(price.duration)}
                    sx={{
                      color: "#9aa3b2",
                      p: 0.5,
                      "&.Mui-checked": { color: BLUE },
                    }}
                  />
                  <Typography sx={{ color: NAVY, fontSize: 16, fontWeight: 500 }}>
                    {price.duration}
                  </Typography>
                </Stack>
                <Box sx={{ textAlign: "right" }}>
                  <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 16 }}>
                    {price.price}
                  </Typography>
                  {price.strikePrice ? (
                    <Typography
                      sx={{
                        textDecoration: "line-through",
                        color: "rgba(106,106,106,0.65)",
                        fontSize: 16,
                        fontWeight: 500,
                      }}
                    >
                      {price.strikePrice}
                    </Typography>
                  ) : null}
                </Box>
              </Stack>
            );
          })}
        </Stack>
      </Box>
      <Box sx={{ borderTop: "1px solid rgba(128,128,128,0.64)", py: 2.5, textAlign: "center" }}>
        <Button
          variant="contained"
          href={canBuy ? plan.buyUrl : undefined}
          target="_blank"
          rel="noopener noreferrer"
          disabled={!canBuy}
          sx={{
            width: 169,
            backgroundColor: BLUE,
            color: "#fff",
            fontWeight: 700,
            borderRadius: "5px",
            boxShadow: "none",
            opacity: canBuy ? 1 : 0.6,
            "&:hover": { backgroundColor: "#5f86d4", boxShadow: "none" },
            "&.Mui-disabled": { backgroundColor: BLUE, color: "#fff", opacity: 0.6 },
          }}
        >
          Buy Plan
        </Button>
      </Box>
    </Box>
  );
}

function resolvePlans(tab?: PlanTab, inner?: PlanInnerTab, group?: PlanGroup): PlanCard[] {
  if (group?.plans?.length) return group.plans;
  if (inner?.plans?.length) return inner.plans;
  if (tab?.plans?.length) return tab.plans;
  return [];
}

export default function Plans({ data }: { data?: HomePlans | null }) {
  const theme = useTheme();
  const twoUp = useMediaQuery(theme.breakpoints.up("md"));
  const [tab, setTab] = useState(0);
  const [inner, setInner] = useState(0);
  const [group, setGroup] = useState(0);
  const [start, setStart] = useState(0);
  const [selected, setSelected] = useState<Record<number, string>>({});
  const [learnMorePlan, setLearnMorePlan] = useState<PlanCard | null>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);

  const current = data?.tabs?.[tab];
  const innerTabs = current?.innerTabs || [];
  const currentInner = innerTabs[inner];
  const groups = currentInner?.groups?.length ? currentInner.groups : current?.groups || [];
  const currentGroup = groups[group];
  const plans = useMemo(
    () => resolvePlans(current, currentInner, currentGroup),
    [current, currentInner, currentGroup]
  );
  const visibleCount = twoUp ? 2 : 1;
  const maxStart = Math.max(0, plans.length - visibleCount);

  useEffect(() => {
    setInner(0);
    setGroup(0);
    setStart(0);
    setSelected({});
  }, [tab]);

  useEffect(() => {
    setGroup(0);
    setStart(0);
    setSelected({});
  }, [inner]);

  useEffect(() => {
    setStart(0);
    setSelected({});
  }, [group]);

  useEffect(() => {
    setStart((value) => Math.min(value, maxStart));
  }, [maxStart]);

  const scrollToIndex = (index: number) => {
    const el = scrollerRef.current;
    if (!el) return;
    const next = Math.max(0, Math.min(index, maxStart));
    const child = el.children[next] as HTMLElement | undefined;
    if (!child) return;
    const left = child.getBoundingClientRect().left - el.getBoundingClientRect().left + el.scrollLeft;
    el.scrollTo({ left, behavior: "smooth" });
    setStart(next);
  };

  useEffect(() => {
    const el = scrollerRef.current;
    if (el) el.scrollTo({ left: 0, behavior: "auto" });
  }, [tab, inner, group, visibleCount]);

  useEffect(() => {
    if (plans.length <= visibleCount || learnMorePlan) return;
    const timer = window.setInterval(() => {
        setStart((value) => {
          const next = value >= maxStart ? 0 : value + 1;
          const el = scrollerRef.current;
          const child = el?.children[next] as HTMLElement | undefined;
          if (el && child) {
            const left =
              child.getBoundingClientRect().left - el.getBoundingClientRect().left + el.scrollLeft;
            el.scrollTo({ left, behavior: "smooth" });
          }
          return next;
        });
    }, 5000);
    return () => window.clearInterval(timer);
  }, [plans.length, visibleCount, maxStart, learnMorePlan, tab, inner, group]);

  if (!data) return null;

  const dotCount = Math.max(1, maxStart + 1);
  const showNav = plans.length > visibleCount;
  const goPrev = () => scrollToIndex(start <= 0 ? maxStart : start - 1);
  const goNext = () => scrollToIndex(start >= maxStart ? 0 : start + 1);
  const cardFlex =
    plans.length === 1
      ? "0 1 480px"
      : { xs: "0 0 100%", sm: "0 0 100%", md: "0 0 calc((100% - 32px) / 2)" };

  return (
    <Box
      sx={{
        py: { xs: 4, sm: 6, md: 8, tv: 10 },
        backgroundColor: "#f5fafe",
        backgroundImage: `url(${plansBg})`,
        backgroundRepeat: "no-repeat",
        backgroundSize: "contain",
        backgroundPosition: "top left",
      }}
    >
      <Container
        maxWidth={false}
        sx={{ maxWidth: { xs: "100%", md: 1200, xl: 1360, tv: 1600 }, px: { xs: 2, sm: 3, md: 4, tv: 8 } }}
      >
        <Typography
          sx={{
            textAlign: "center",
            color: NAVY,
            fontSize: { xs: 22, sm: 26, md: 32, lg: 36, tv: 44 },
            fontWeight: 700,
            lineHeight: 1.15,
            mb: { xs: 3, md: 5 },
          }}
        >
          <Heading title={data.title} highlight={data.highlight} />
        </Typography>

        <Stack
          direction="row"
          justifyContent="center"
          flexWrap="wrap"
          useFlexGap
          sx={{ gap: { xs: 1, md: 1.25 }, mb: { xs: 3, md: 4 } }}
        >
          {(data.tabs || []).map((item, index) => {
            const active = tab === index;
            return (
              <Button
                key={item.id || item.name}
                onClick={() => setTab(index)}
                sx={{
                  minWidth: { xs: 80, sm: 100, md: 140 },
                  color: active ? "#fff" : BLUE,
                  fontWeight: 600,
                  fontSize: { xs: 12, sm: 13, md: 16, tv: 18 },
                  textTransform: "none",
                  borderRadius: "8px",
                  border: "1px solid #759ae1",
                  backgroundColor: active ? BLUE : "#fff",
                  "&:hover": {
                    backgroundColor: active ? "#5f86d4" : "rgba(117,154,225,0.12)",
                    border: "1px solid #759ae1",
                  },
                }}
              >
                {item.name}
              </Button>
            );
          })}
        </Stack>

        {innerTabs.length ? (
          <Stack
            direction="row"
            justifyContent="center"
            flexWrap="wrap"
            useFlexGap
            sx={{ gap: 1, mb: { xs: 2.5, md: 3.5 } }}
          >
            {innerTabs.map((item, index) => {
              const active = inner === index;
              return (
                <Button
                  key={item.id || item.name}
                  onClick={() => setInner(index)}
                  sx={{
                    minWidth: { xs: 90, sm: 110, md: 140 },
                    color: "#fff",
                    backgroundColor: "#ff8902 !important",
                    border: "1px solid #ff8902",
                    fontWeight: 600,
                    fontSize: { xs: 13, md: 15 },
                    textTransform: "none",
                    borderRadius: "8px",
                    opacity: active ? 1 : 0.72,
                    "&:hover": {
                      backgroundColor: "#ff8902 !important",
                      opacity: 1,
                    },
                  }}
                >
                  {item.name}
                </Button>
              );
            })}
          </Stack>
        ) : null}

        {groups.length ? (
          <Stack
            direction="row"
            justifyContent="center"
            flexWrap="wrap"
            useFlexGap
            sx={{ gap: { xs: 1.5, md: 2 }, mb: { xs: 3, md: 4 } }}
          >
            {groups.map((item, index) => (
              <Box
                key={item.id || item.name}
                component="label"
                onClick={() => setGroup(index)}
                sx={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 0.75,
                  cursor: "pointer",
                  color: NAVY,
                  fontSize: { xs: 13, md: 16 },
                  fontWeight: 500,
                  border: "1px solid #d5dbe6",
                  borderRadius: "8px",
                  px: 1.5,
                  py: 0.75,
                  backgroundColor: group === index ? "rgba(117,154,225,0.10)" : "#fff",
                }}
              >
                {item.name}
                <Radio
                  checked={group === index}
                  onChange={() => setGroup(index)}
                  sx={{
                    p: 0.25,
                    color: "#9aa3b2",
                    "&.Mui-checked": { color: BLUE },
                  }}
                />
              </Box>
            ))}
          </Stack>
        ) : null}

        <Box sx={{ position: "relative", maxWidth: 1080, mx: "auto", px: { xs: 5, md: 7 } }}>
          <Box
            ref={scrollerRef}
            onScroll={(event) => {
              const el = event.currentTarget;
              const first = el.children[0] as HTMLElement | undefined;
              if (!first) return;
              const gap = twoUp ? 32 : 20;
              const index = Math.round(el.scrollLeft / (first.offsetWidth + gap));
              setStart(Math.max(0, Math.min(index, maxStart)));
            }}
            sx={{
              display: "flex",
              alignItems: "stretch",
              justifyContent: plans.length === 1 ? "center" : "flex-start",
              gap: { xs: 2.5, md: 4 },
              overflowX: "auto",
              scrollSnapType: "x mandatory",
              scrollBehavior: "smooth",
              pb: 0.5,
              scrollbarWidth: "none",
              "&::-webkit-scrollbar": { display: "none" },
            }}
          >
            {plans.map((plan, index) => {
              const key = plan.id || index;
              return (
                <Box
                  key={plan.id || `${plan.title}-${index}`}
                  sx={{
                    flex: cardFlex,
                    maxWidth: plans.length === 1 ? 480 : "none",
                    minWidth: 0,
                    scrollSnapAlign: "start",
                    display: "flex",
                  }}
                >
                  <PlanItem
                    plan={plan}
                    selected={selected[key] || ""}
                    onSelect={(duration) => setSelected((prev) => ({ ...prev, [key]: duration }))}
                    onLearnMore={() => setLearnMorePlan(plan)}
                  />
                </Box>
              );
            })}
          </Box>

          {showNav ? (
            <>
              <IconButton
                onClick={goPrev}
                aria-label="Previous plans"
                sx={{
                  position: "absolute",
                  left: 0,
                  top: "45%",
                  zIndex: 2,
                  transform: "translateY(-50%)",
                  backgroundColor: "#fff",
                  boxShadow: "0 2px 10px rgba(0,0,0,0.12)",
                  "&:hover": { backgroundColor: "#fff" },
                }}
              >
                <ChevronLeftIcon />
              </IconButton>
              <IconButton
                onClick={goNext}
                aria-label="Next plans"
                sx={{
                  position: "absolute",
                  right: 0,
                  top: "45%",
                  zIndex: 2,
                  transform: "translateY(-50%)",
                  backgroundColor: "#fff",
                  boxShadow: "0 2px 10px rgba(0,0,0,0.12)",
                  "&:hover": { backgroundColor: "#fff" },
                }}
              >
                <ChevronRightIcon />
              </IconButton>
            </>
          ) : null}
        </Box>

        {showNav ? (
          <Stack direction="row" justifyContent="center" spacing={1.25} sx={{ mt: 3 }}>
            {Array.from({ length: dotCount }).map((_, index) => (
              <Box
                key={index}
                onClick={() => scrollToIndex(index)}
                sx={{
                  width: 10,
                  height: 10,
                  borderRadius: "50%",
                  cursor: "pointer",
                  backgroundColor: start === index ? BLUE : "rgba(117,154,225,0.35)",
                }}
              />
            ))}
          </Stack>
        ) : null}
      </Container>
      <PlanLearnMoreModal
        open={Boolean(learnMorePlan)}
        title={learnMorePlan?.title}
        content={learnMorePlan?.learnMore}
        onClose={() => setLearnMorePlan(null)}
      />
    </Box>
  );
}
